	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`enrichable_person_count expected to be basetypes.Int64Value, was: %T`, enrichablePersonCountAttribute))
	}

	enrichableResidenceCountAttribute, ok := attributes["enrichable_residence_count"]

